INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is the purpose of an ''oxidation'' step after vat or sulphur dye application (once the reduced/soluble form has penetrated the fiber)?', '["To convert the soluble, colorless (or differently colored) leuco form of the dye back into its original insoluble, colored, wash-fast form inside the fiber","To dissolve the dye completely out of the fiber for removal","To apply an entirely new second dye color over the first","To reduce the fabric''s final GSM by removing fiber mass"]'::jsonb, 'To convert the soluble, colorless (or differently colored) leuco form of the dye back into its original insoluble, colored, wash-fast form inside the fiber', 'After the reduced (soluble) leuco form of a vat or sulphur dye has penetrated into the fiber, exposure to air or an oxidizing agent converts it back into its stable, insoluble, colored state — trapped inside the fiber structure, giving good wash fastness.', 1, '{"oxidation-step","vat-dye"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why is proper rinsing/washing after any bleaching step critical before proceeding to dyeing?', '["Residual bleaching chemicals (like peroxide) left in the fabric can interfere with subsequent dye chemistry or continue reacting, causing shade/fastness problems","Rinsing after bleaching has no effect on subsequent dyeing performance","Bleaching chemicals always evaporate completely on their own with no rinsing needed","Rinsing is only relevant for printing, never for dyeing after bleaching"]'::jsonb, 'Residual bleaching chemicals (like peroxide) left in the fabric can interfere with subsequent dye chemistry or continue reacting, causing shade/fastness problems', 'Leftover peroxide (or its breakdown products) can continue oxidizing/interfering with dye molecules during subsequent dyeing, potentially causing shade problems, reduced dye yield, or fastness issues — thorough rinsing after bleaching removes these residual reactive chemicals first.', 2, '{"post-bleach-rinsing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is a ''batch-to-batch'' shade variation problem, and what commonly causes it in dyeing?', '["Different production lots processed under slightly different conditions (temperature, time, water quality, raw material) produce noticeably different final shades despite using the same nominal recipe","It refers only to variation in fabric width between production batches, unrelated to color","This term describes a defect that can only occur in printing, never in solid dyeing","Batch-to-batch shade variation is impossible if the same dye recipe is used, regardless of any other factor"]'::jsonb, 'Different production lots processed under slightly different conditions (temperature, time, water quality, raw material) produce noticeably different final shades despite using the same nominal recipe', 'Even with an identical dye recipe on paper, real-world variation in exact temperature control, timing, water quality, or raw fiber/yarn lot properties between different production batches can cause the final achieved shade to differ noticeably — a persistent practical challenge requiring careful process standardization and monitoring.', 2, '{"batch-to-batch-variation"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What role does a ''dyeing machine''s liquor circulation system'' (pumps, nozzles) play in achieving good dyeing results?', '["It ensures dye liquor moves consistently past/through all parts of the fabric or yarn package, promoting even exhaustion and preventing localized shade variation","Liquor circulation exists purely to heat the water, with no relationship to dye distribution","Circulation systems are only used for rinsing, never during the actual dyeing/coloring stage","Good circulation always guarantees perfect results regardless of any other process parameter"]'::jsonb, 'It ensures dye liquor moves consistently past/through all parts of the fabric or yarn package, promoting even exhaustion and preventing localized shade variation', 'Consistent liquor circulation (via pumps/nozzles moving liquor past or through the substrate) helps ensure every part of the fabric/yarn is exposed to fresh, well-mixed dye liquor at a similar rate, which is essential for even dye exhaustion and avoiding localized under- or over-dyed areas.', 1, '{"liquor-circulation"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What does ''GSM tolerance'' typically specify in a buyer''s fabric quality requirement?', '["The acceptable range of variation (plus/minus a certain amount) allowed around the target fabric weight per square meter","The exact color shade tolerance for a dyeing recipe","The maximum allowable fabric width variation only","The percentage of synthetic fiber allowed in a natural fiber blend"]'::jsonb, 'The acceptable range of variation (plus/minus a certain amount) allowed around the target fabric weight per square meter', 'Since achieving an exact GSM every single time is impractical, buyers typically specify a tolerance range (e.g., target GSM ±5%) within which the actual measured fabric weight must fall to be considered acceptable/compliant.', 1, '{"gsm-tolerance"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why might a fabric''s actual measured GSM fall outside the buyer''s specified tolerance, even if the correct yarn count and weave construction were used?', '["Variations in processing (shrinkage during wet processing/finishing, tension control, drying) can shift the final GSM even when yarn count and construction were correctly executed","GSM is determined ONLY by yarn count and construction, with zero influence from any wet-processing or finishing step","Actual GSM can never differ from the theoretical calculated GSM under any circumstances","GSM tolerance issues can only be caused by using the wrong fiber type, never by processing variation"]'::jsonb, 'Variations in processing (shrinkage during wet processing/finishing, tension control, drying) can shift the final GSM even when yarn count and construction were correctly executed', 'Even with correct yarn count/construction, actual finished GSM is also affected by how much the fabric shrinks or relaxes during wet processing and finishing (stenter width control, drying tension, etc.) — inconsistent processing can shift the final GSM outside the buyer''s tolerance despite correct raw material specifications.', 2, '{"gsm-variation","processing-effect"}'::text[]);
